#!/usr/bin/env python3
"""Einmaliger Repo-Cleanup für die gebündelten Prioritäten B, C und D.

Das Skript bleibt absichtlich im Repository liegen und löscht sich nicht selbst.
Es verändert keine GitHub-Workflow-Dateien und keine A-Prioritäten.
"""
from __future__ import annotations
from pathlib import Path
import hashlib
import json
import re

ROOT = Path(__file__).resolve().parents[2]
CSS_TARGETS = {'assets/css/components/accessibility.css': {'before_sha256': '3b8c22506f814f65af2e75c0f539276272770189ed843f2e888cd6d2a6ac6e81', 'after_sha256': '5ed7cf5a8e78f7a40365ab16c7f3db9e4d85398725881e4cfbedb1d423cfa233', 'content': '/* Globale Hilfen für Barrierefreiheit. */\n\n/* Tastatur-Navigation direkt zum Hauptinhalt */\n.skip-link {\n    position: fixed;\n    top: var(--space-m);\n    left: var(--space-m);\n    z-index: 5000;\n    padding: var(--space-m) var(--space-l);\n    border-radius: var(--space-s);\n    background: var(--accent);\n    color: var(--text-on-newsSlide);\n    font-weight: 700;\n    text-decoration: none;\n    transform: translateY(calc(-100% - 30px));\n    transition: transform 0.2s ease;\n}\n\n.skip-link:focus,\n.skip-link:focus-visible {\n    transform: translateY(0);\n    outline: 3px solid var(--text-main);\n    outline-offset: 2px;\n}\n\n#main-content:focus {\n    outline: none;\n}\n\n/* Semantische, aber visuell nicht benötigte Inhalte */\n.visually-hidden {\n    position: absolute !important;\n    width: 1px !important;\n    height: 1px !important;\n    padding: 0 !important;\n    margin: -1px !important;\n    overflow: hidden !important;\n    clip: rect(0, 0, 0, 0) !important;\n    white-space: nowrap !important;\n    border: 0 !important;\n}\n\ncaption.visually-hidden {\n    position: absolute !important;\n}\n\n@media (prefers-reduced-motion: reduce) {\n    html {\n        scroll-behavior: auto;\n    }\n\n    .skip-link {\n        transition: none !important;\n    }\n}\n'}, 'assets/css/components/animations.css': {'before_sha256': '264bf09defb4004aceb7ea1e6100a477c0a34da22578297133636a611ad98abf', 'after_sha256': '13804a508f2c8fa4edf78aecc9715f2cc7c0f688c700b2393047f45086aa0cc3', 'content': '/* Grundlegende Animationen. Aus style.css unverändert ausgelagert. */\n\n/* =========================================\n   ===== 7. ANIMATION ======================\n   ========================================= */\n\n.animate {\n    opacity: 0;\n    transform: translateY(40px);\n    animation: fadeInUp 0.6s ease forwards;\n}\n\n@keyframes fadeInUp {\n    to {\n        opacity: 1;\n        transform: translateY(0);\n    }\n}\n\n@media (prefers-reduced-motion: reduce) {\n    .animate {\n        opacity: 1 !important;\n        transform: none !important;\n        animation: none !important;\n    }\n}\n'}, 'assets/css/components/contact-form.css': {'before_sha256': '56c5bf3af0937154d9fed286984e2e93753056f46c9f549282959701f4248e4a', 'after_sha256': 'bbab50e44bc480a422b6ad7248471d2519b9b5472bfd82bda111458a21152031', 'content': '/* Kontaktformular. */\n\n/* =========================================\n   ===== KONTAKTFORMULAR ===================\n   ========================================= */\n\n.contact-section {\n    width: 100%;\n    max-width: 100%;\n    min-width: 0;\n    margin: var(--space-xl) auto;\n    padding: var(--space-m);\n}\n\n.contact-form {\n    display: flex;\n    flex-direction: column;\n    width: 100%;\n    max-width: 100%;\n    min-width: 0;\n    gap: var(--space-m);\n    padding: var(--space-xl);\n    border-radius: var(--space-m);\n    background: var(--bg-secondary);\n    box-shadow: var(--shadow-light);\n}\n\n.contact-form h1,\n.contact-form h2 {\n    text-align: center;\n}\n\n.contact-submit-button.is-sending {\n    background-color: var(--warning);\n    color: #222;\n}\n\n.contact-submit-button.is-success {\n    background-color: var(--success);\n    color: white;\n}\n\n.contact-submit-button.is-error {\n    background-color: var(--error);\n    color: white;\n}\n\n.form-group {\n    display: flex;\n    flex-direction: column;\n    min-width: 0;\n    gap: var(--space-s);\n}\n\n.form-group input,\n.form-group textarea {\n    padding: var(--space-m);\n    border: 1px solid #334155;\n    border-radius: var(--space-s);\n    background: var(--bg-main);\n    color: var(--text-main);\n    font-size: 1rem;\n    transition: border 0.2s ease, box-shadow 0.2s ease;\n}\n\n.form-group input:focus,\n.form-group textarea:focus {\n    outline: none;\n    border-color: var(--accent);\n    box-shadow: 0 0 0 2px rgba(56, 189, 248, 0.2);\n}\n\n.form-consent {\n    flex-direction: row;\n    align-items: flex-start;\n    width: 100%;\n    gap: var(--space-s);\n}\n\n.form-consent input {\n    margin-top: 3px;\n}\n\n.form-consent input[type="checkbox"] {\n    flex: 0 0 auto;\n    width: auto;\n    min-width: auto;\n}\n\n.form-consent label {\n    min-width: 0;\n    overflow-wrap: anywhere;\n}\n\n.contact-form button {\n    margin-top: var(--space-s);\n}\n\n.contact-form :where(input:not([type="checkbox"]), textarea, button) {\n    width: 100%;\n    max-width: 100%;\n    min-width: 0;\n}\n\n.contact-form textarea {\n    resize: vertical;\n}\n\n.form-status {\n    min-height: 1.2em;\n    color: var(--text-muted);\n    font-size: 0.9rem;\n    text-align: center;\n}\n\n.form-status.success {\n    color: #22c55e;\n}\n\n.form-status.error {\n    color: #ef4444;\n}\n\n@media (max-width: 480px) {\n    .contact-form {\n        padding: var(--space-l);\n    }\n}\n'}, 'assets/css/components/gallery.css': {'before_sha256': 'f4bc8029ac7dd9242083fc2fe6de8c0eb2f6eb971c27ab4d2caa1ea78a2467c3', 'after_sha256': '6f2c3bd77fe7589ee57eeebe938d76f620c34e0c04a719792c7b5853ed2fa3b4', 'content': '/* Historische Fotos und Galerie. */\n\n/* =========================================\n   ===== HISTORISCHE FOTOS =================\n   ========================================= */\n\n.content.images-page {\n    display: grid;\n    grid-template-columns: 280px minmax(0, 1fr);\n    gap: var(--space-xl);\n    padding: var(--space-m) var(--space-xl);\n    align-items: start;\n}\n\n.images-page__banner {\n    grid-column: 1 / -1;\n    grid-row: 1;\n}\n\n.images-event-list {\n    grid-column: 1;\n    grid-row: 2;\n}\n\n.images-content {\n    grid-column: 2;\n    grid-row: 2;\n    min-width: 0;\n}\n\n.images-loading {\n    margin-top: 0;\n}\n\n.images-gallery h3 {\n    margin-bottom: var(--space-l);\n}\n\n.images-event-list h2 {\n    margin-bottom: var(--space-l);\n}\n\n.images-event-list__header {\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    gap: var(--space-m);\n    margin-bottom: var(--space-l);\n}\n\n.images-event-list__header h2 {\n    flex: 1;\n    margin-bottom: 0;\n}\n\n.images-event-button {\n    display: block;\n    width: 100%;\n    margin-bottom: var(--space-s);\n    padding: var(--space-m);\n    border: none;\n    border-radius: var(--space-m);\n    background: var(--bg-main);\n    color: var(--text-main);\n    box-shadow: var(--shadow-light);\n    font: inherit;\n    text-align: left;\n    white-space: normal;\n    overflow-wrap: anywhere;\n    hyphens: auto;\n    cursor: pointer;\n    transition:\n        background 0.2s ease,\n        color 0.2s ease,\n        transform 0.2s ease,\n        box-shadow 0.2s ease;\n}\n\n.images-event-button:hover {\n    background: var(--accent-hover);\n    color: var(--text-on-newsSlide);\n    transform: translateX(3px);\n    box-shadow: var(--shadow-heavy);\n}\n\n.images-event-button.is-active {\n    background: var(--accent);\n    color: var(--text-on-newsSlide);\n}\n\n.images-event-button[aria-pressed="true"] {\n    outline: 2px solid var(--accent);\n    outline-offset: 2px;\n}\n\n.images-event-button:focus {\n    outline: 2px solid var(--accent);\n    outline-offset: 2px;\n}\n\n.masonry-gallery {\n    column-count: 3;\n    column-gap: var(--space-m);\n}\n\n.masonry-gallery img {\n    display: block;\n    width: 100%;\n    margin-bottom: var(--space-m);\n    border-radius: var(--space-m);\n    box-shadow: var(--shadow-light);\n    break-inside: avoid;\n    -webkit-column-break-inside: avoid;\n    transition: transform 0.2s ease, box-shadow 0.2s ease;\n}\n\n.masonry-gallery img:hover {\n    transform: scale(1.02);\n    box-shadow: var(--shadow-heavy);\n    cursor: pointer;\n}\n\n.images-nav-toggle,\n.images-nav-close,\n.images-nav-backdrop {\n    display: none;\n}\n\n/* Die Navigationsbox ist zugleich eine .box und wird daher vom allgemeinen\n   Animationsmodul markiert. Ihre Positionierung darf dadurch nicht verändert werden. */\n.images-event-list.animate {\n    opacity: 1;\n    transform: none;\n    animation: none;\n}\n\n@media (max-width: 768px) {\n    .content.images-page {\n        grid-template-columns: minmax(0, 1fr);\n        padding: var(--space-m);\n    }\n\n    .masonry-gallery {\n        column-count: 2;\n    }\n\n    .images-page__banner,\n    .images-nav-toggle,\n    .images-content {\n        grid-column: 1;\n    }\n\n    .images-page__banner {\n        grid-row: 1;\n    }\n\n    .images-nav-toggle {\n        display: inline-flex;\n        grid-row: 2;\n        align-items: center;\n        justify-content: center;\n        justify-self: start;\n        gap: 0.55rem;\n        min-height: 44px;\n        margin: 0;\n        padding: 0.62rem 1rem;\n        border: 1px solid rgba(56, 189, 248, 0.72);\n        border-radius: 999px;\n        background: linear-gradient(\n            180deg,\n            rgba(30, 41, 59, 0.96),\n            rgba(15, 23, 42, 0.96)\n        );\n        color: var(--text-main);\n        box-shadow:\n            0 6px 18px rgba(2, 6, 23, 0.24),\n            inset 0 1px 0 rgba(255, 255, 255, 0.04);\n        font: inherit;\n        font-size: 0.94rem;\n        font-weight: 700;\n        line-height: 1;\n        cursor: pointer;\n        transition:\n            border-color 0.18s ease,\n            background 0.18s ease,\n            color 0.18s ease,\n            box-shadow 0.18s ease,\n            transform 0.18s ease;\n    }\n\n    .images-nav-toggle:hover {\n        border-color: var(--accent);\n        background: linear-gradient(\n            180deg,\n            rgba(51, 65, 85, 0.98),\n            rgba(30, 41, 59, 0.98)\n        );\n        color: #ffffff;\n        box-shadow:\n            0 8px 22px rgba(2, 6, 23, 0.32),\n            0 0 0 1px rgba(56, 189, 248, 0.12);\n        transform: translateY(-1px);\n    }\n\n    .images-nav-toggle:focus-visible {\n        outline: 3px solid rgba(56, 189, 248, 0.42);\n        outline-offset: 3px;\n    }\n\n    .images-nav-toggle[aria-expanded="true"] {\n        border-color: var(--accent);\n        background: rgba(56, 189, 248, 0.16);\n        color: var(--accent);\n    }\n\n    .images-nav-toggle__icon {\n        display: inline-grid;\n        place-items: center;\n        width: 1.35rem;\n        height: 1.35rem;\n        color: var(--accent);\n        font-size: 1.05rem;\n        line-height: 1;\n    }\n\n    .images-nav-toggle__label {\n        white-space: nowrap;\n    }\n\n    .images-content {\n        grid-row: 3;\n    }\n\n    .images-event-list,\n    .images-event-list.animate {\n        position: fixed;\n        top: 0;\n        bottom: 0;\n        left: 0;\n        z-index: 4100;\n        display: block;\n        width: min(86vw, 320px);\n        max-height: 100dvh;\n        margin: 0;\n        overflow-y: auto;\n        border-radius: 0 var(--space-m) var(--space-m) 0;\n        opacity: 1;\n        transform: translateX(-105%);\n        animation: none;\n        transition: transform 0.25s ease;\n    }\n\n    .images-event-list.is-open,\n    .images-event-list.animate.is-open {\n        transform: translateX(0);\n    }\n\n    .images-event-list__header {\n        justify-content: space-between;\n    }\n\n    .images-nav-close {\n        position: relative;\n        z-index: 1;\n        display: inline-grid;\n        place-items: center;\n        flex: 0 0 auto;\n        width: 40px;\n        height: 40px;\n        border: 1px solid var(--accent);\n        border-radius: var(--space-s);\n        background: transparent;\n        color: var(--text-main);\n        font: inherit;\n        font-size: 1.5rem;\n        line-height: 1;\n        pointer-events: auto;\n        cursor: pointer;\n    }\n\n    .images-nav-backdrop {\n        position: fixed;\n        inset: 0;\n        z-index: 4000;\n        width: 100%;\n        height: 100%;\n        border: 0;\n        background: rgba(2, 6, 23, 0.72);\n        opacity: 0;\n        pointer-events: none;\n        transition: opacity 0.25s ease;\n    }\n\n    .images-nav-backdrop.is-visible {\n        display: block;\n        opacity: 1;\n        pointer-events: auto;\n    }\n\n    body.gallery-nav-open {\n        overflow: hidden;\n    }\n}\n\n@media (max-width: 480px) {\n    .masonry-gallery {\n        column-count: 1;\n    }\n}\n\n@media (prefers-reduced-motion: reduce) {\n    .images-event-list,\n    .images-nav-backdrop,\n    .images-nav-toggle {\n        transition: none;\n    }\n}\n'}, 'assets/css/components/maps-consent.css': {'before_sha256': 'a90d6302848666dd2245f255388508ddf8400ba4c7c700c3657501565ea9d5d5', 'after_sha256': 'dec8dbff67fa7ce368c03abe9ad6ae8da7e680410fe263c19ae0e2ec8a475ee7', 'content': '/* Karten und Einwilligung für externe Inhalte. Aus style.css unverändert ausgelagert. */\n\n/* =========================================\n   ===== 13. MAP DESIGN ====================\n   ========================================= */\n\n.map-container {\n    margin-top: var(--space-m);\n    border-radius: var(--space-m);\n    overflow: hidden;\n    box-shadow: var(--shadow-light);\n}\n\n.map-container iframe {\n    width: 100%;\n    height: 250px;\n    border: 0;\n    display: block;\n}\n\n\n/* =========================================\n   ===== 14. BUTTON FUER DSGVO =============\n   ========================================= */\n\n.iframe-consent {\n    width: 100%;\n    height: 100%;\n    min-height: 200px;\n\n    display: flex;\n    flex-direction: column;\n    justify-content: center;\n    align-items: center;\n\n    background: var(--bg-secondary);\n    text-align: center;\n    padding: var(--space-m);\n}\n\n.iframe-consent button {\n    margin-top: var(--space-s);\n}\n\n.iframe-embed__controls {\n    display: flex;\n    flex-wrap: wrap;\n    align-items: center;\n    justify-content: space-between;\n    width: 100%;\n    gap: var(--space-m);\n    padding: var(--space-m);\n    background: var(--bg-navigation);\n    color: var(--text-muted);\n    font-size: 0.9rem;\n}\n\n.iframe-revoke-button {\n    padding: var(--space-s) var(--space-m);\n    border: 1px solid var(--accent);\n    border-radius: var(--space-s);\n    background: transparent;\n    color: var(--text-main);\n    font: inherit;\n    cursor: pointer;\n}\n\n.iframe-revoke-button:hover,\n.iframe-revoke-button:focus-visible {\n    background: var(--accent);\n    color: var(--text-on-newsSlide);\n}\n\n.iframe-revoke-button:focus-visible {\n    outline: 3px solid var(--accent);\n    outline-offset: 2px;\n}\n\n@media (max-width: 480px) {\n    .map-container iframe {\n        height: 220px;\n    }\n\n    .iframe-embed__controls {\n        flex-direction: column;\n        align-items: stretch;\n        text-align: center;\n    }\n}\n'}, 'assets/css/components/news-slider.css': {'before_sha256': '7654058ff8177e091c66fc59871d0858036523279264b2fde5e562a26b1ccd4c', 'after_sha256': '29134532c4247149f3b90bc8865fb2a1fb992139c9ffd2d77ed7c102fa0d37c4', 'content': '/* News-Slider. */\n\n/* =========================================\n   ===== NEWS SLIDER =======================\n   ========================================= */\n\n.news-slider {\n    position: relative;\n    overflow: hidden;\n    min-width: 100px;\n    min-height: 420px;\n    border-radius: var(--space-m);\n}\n\n.news-slide {\n    position: absolute;\n    inset: 0;\n    display: block;\n    padding: var(--space-l);\n    background: var(--bg-secondary);\n    opacity: 0;\n    transition: opacity 0.6s ease;\n}\n\n.news-slide.active {\n    opacity: 1;\n}\n\n.news-slide img {\n    width: 100%;\n    max-height: 70%;\n    object-fit: cover;\n    border-radius: var(--space-m);\n}\n\n.news-slide a {\n    width: fit-content;\n    margin-top: auto;\n    padding: 8px 12px;\n    border-radius: var(--space-m);\n    background: var(--accent);\n    color: var(--text-on-newsSlide);\n    text-decoration: none;\n}\n\n.news-slide a:hover {\n    background: var(--accent-hover);\n}\n\n.news-slider--has-footer .news-slide {\n    padding-bottom: 76px;\n}\n\n.news-slider--controlled .news-slide {\n    padding-bottom: 72px;\n    pointer-events: none;\n}\n\n.news-slider--controlled .news-slide.active {\n    pointer-events: auto;\n}\n\n.news-slide__body {\n    display: flex;\n    flex-direction: column;\n    height: 100%;\n    min-height: 0;\n    gap: var(--space-s);\n}\n\n.news-slide__copy {\n    flex: 0 0 auto;\n    min-width: 0;\n}\n\n.news-slide__copy p {\n    overflow-wrap: anywhere;\n}\n\n.news-slide__media {\n    order: -1;\n    flex: 1 1 auto;\n    min-height: 150px;\n    overflow: hidden;\n    border-radius: var(--space-m);\n}\n\n.news-slide__media img {\n    display: block;\n    width: 100%;\n    height: 100%;\n    max-height: none;\n    object-fit: cover;\n    border-radius: inherit;\n}\n\n.news-slide--without-image .news-slide__copy {\n    flex: 1;\n}\n\n.news-slider__footer {\n    position: absolute;\n    right: var(--space-m);\n    bottom: var(--space-m);\n    left: var(--space-m);\n    z-index: 10;\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    gap: var(--space-m);\n    pointer-events: none;\n}\n\n.news-slider__read-more,\n.news-slider__controls {\n    pointer-events: auto;\n}\n\n.news-slider__read-more {\n    display: inline-flex;\n    align-items: center;\n    min-height: 42px;\n    margin: 0;\n    padding: 0 var(--space-l);\n    border-radius: var(--space-m);\n    background: var(--accent);\n    color: var(--text-on-newsSlide);\n    text-decoration: none;\n    white-space: nowrap;\n}\n\n.news-slider__read-more:hover,\n.news-slider__read-more:focus-visible {\n    background: var(--accent-hover);\n}\n\n.news-slider__read-more[hidden] {\n    display: none;\n}\n\n.news-slider__controls {\n    position: absolute;\n    right: var(--space-m);\n    bottom: var(--space-m);\n    z-index: 10;\n    display: flex;\n    align-items: center;\n    gap: var(--space-s);\n    margin-left: auto;\n    padding: var(--space-s);\n    border-radius: var(--space-m);\n    background: rgba(2, 6, 23, 0.9);\n    box-shadow: var(--shadow-light);\n}\n\n.news-slider__button {\n    min-width: 42px;\n    min-height: 42px;\n    padding: 0 var(--space-m);\n    border: 1px solid var(--accent);\n    border-radius: var(--space-s);\n    background: var(--bg-secondary);\n    color: var(--text-main);\n    font: inherit;\n    font-weight: 700;\n    cursor: pointer;\n}\n\n.news-slider__button:hover {\n    background: var(--accent);\n    color: var(--text-on-newsSlide);\n}\n\n.news-slider__button:focus-visible {\n    outline: 3px solid var(--accent);\n    outline-offset: 2px;\n}\n\n.news-slider__button--toggle {\n    min-width: 100px;\n}\n\n.news-slider__status {\n    min-width: 48px;\n    color: var(--text-main);\n    font-variant-numeric: tabular-nums;\n    text-align: center;\n}\n\n@media (max-width: 768px) {\n    .news-slider {\n        min-height: 340px;\n    }\n\n    .news-slider--has-footer .news-slide {\n        padding: var(--space-m);\n        padding-bottom: 66px;\n    }\n\n    .news-slide__body {\n        display: grid;\n        grid-template-columns: minmax(0, 2fr) minmax(90px, 1fr);\n        align-items: stretch;\n        gap: var(--space-m);\n    }\n\n    .news-slide--without-image .news-slide__body {\n        grid-template-columns: 1fr;\n    }\n\n    .news-slide__copy {\n        overflow: hidden;\n    }\n\n    .news-slide__copy h3 {\n        font-size: 1.05rem;\n        line-height: 1.25;\n    }\n\n    .news-slide__copy p {\n        display: -webkit-box;\n        overflow: hidden;\n        -webkit-box-orient: vertical;\n        -webkit-line-clamp: 7;\n        line-clamp: 7;\n        font-size: 0.94rem;\n    }\n\n    .news-slide__media {\n        order: 0;\n        min-width: 0;\n        min-height: 0;\n        height: 100%;\n    }\n\n    .news-slider__footer {\n        right: var(--space-s);\n        bottom: var(--space-s);\n        left: var(--space-s);\n        gap: var(--space-s);\n    }\n\n    .news-slider__read-more {\n        min-height: 36px;\n        padding: 0 var(--space-m);\n        font-size: 0.88rem;\n    }\n\n\n\n\n}\n\n@media (max-width: 480px) {\n    .news-slider {\n        min-height: 360px;\n    }\n\n    .news-slide__body {\n        grid-template-columns: minmax(0, 2fr) minmax(82px, 1fr);\n        gap: var(--space-s);\n    }\n\n    .news-slide__copy p {\n        -webkit-line-clamp: 8;\n        line-clamp: 8;\n        font-size: 0.88rem;\n    }\n\n    .news-slider__footer {\n        flex-wrap: nowrap;\n    }\n\n    .news-slider__read-more {\n        padding: 0 0.55rem;\n    }\n\n    .news-slider__controls {\n        right: var(--space-s);\n        bottom: var(--space-s);\n        left: var(--space-s);\n        justify-content: center;\n    }\n\n    .news-slider__button {\n        min-width: 40px;\n        min-height: 40px;\n    }\n\n    .news-slider__button--toggle {\n        min-width: 88px;\n    }\n}\n\n@media (prefers-reduced-motion: reduce) {\n    .news-slide {\n        transition: none !important;\n    }\n}\n'}, 'assets/css/components/tables.css': {'before_sha256': 'c937e7bf5ddfb8577ab2fb84e541a4646f0e16e4a35dd5fcd49b80a2a78978cd', 'after_sha256': '8ab0c342e23b041ddeea499019dfe18171c9c882ff37394ffefba4d89cdec5aa', 'content': '/* Tabellen, responsive Spieltabellen und ewige Rangliste. */\n\n/* =========================================\n   ===== TABELLEN: BASIS ====================\n   ========================================= */\n\ntable {\n    width: 100%;\n    border-collapse: collapse;\n    margin-top: var(--space-m);\n}\n\ntd,\nth {\n    padding: var(--space-m);\n    text-align: left;\n    border-bottom: 1px solid #334155;\n}\n\ntable thead th {\n    color: var(--accent);\n}\n\ntable tbody th {\n    color: var(--text-main);\n    font-weight: 400;\n}\n\ntable.table--emphasis-first-column tbody th {\n    color: var(--text-main);\n    font-weight: 600;\n}\n\ntable tr:hover {\n    background: rgba(56, 189, 248, 0.1);\n}\n\n/* Lade-, Leer- und Fehlerzustände innerhalb dynamischer Tabellen. */\n.table-status-row td {\n    width: auto;\n    text-align: center;\n    font-weight: 500;\n    white-space: normal;\n}\n\n.table-status-row--error td {\n    color: var(--text-main);\n    background: rgba(198, 40, 40, 0.18);\n}\n\n.table-status-row--empty td {\n    color: var(--text-muted);\n}\n\n/* =========================================\n   ===== TABELLEN: SCROLL-CONTAINER =========\n   ========================================= */\n\n.table-scroll {\n    width: 100%;\n    max-width: 100%;\n    margin-top: var(--space-m);\n    overflow-x: auto;\n    overscroll-behavior-inline: contain;\n    -webkit-overflow-scrolling: touch;\n}\n\n.table-scroll > table {\n    margin-top: 0;\n}\n\n.table-scroll--wide > table {\n    min-width: 700px;\n}\n\n.table-scroll--wide:focus-visible {\n    outline: 2px solid var(--accent);\n    outline-offset: 3px;\n    border-radius: var(--space-s);\n}\n\n/* =========================================\n   ===== SPIELTABELLEN: RESPONSIVE HILFEN ===\n   ========================================= */\n\n.responsive-label--mobile,\n.responsive-value--mobile,\n.table-mobile-only,\n.venue-compact {\n    display: none;\n}\n\n.venue-compact {\n    position: relative;\n    align-items: center;\n    justify-content: center;\n}\n\n.venue-badge {\n    display: inline-grid;\n    place-items: center;\n    width: 1.75rem;\n    height: 1.75rem;\n    padding: 0;\n    border: 1px solid var(--accent);\n    border-radius: 999px;\n    background: rgba(56, 189, 248, 0.12);\n    color: var(--accent);\n    font: inherit;\n    font-size: 0.78rem;\n    font-weight: 800;\n    line-height: 1;\n    cursor: help;\n}\n\n.venue-badge--away {\n    border-color: #94a3b8;\n    background: rgba(148, 163, 184, 0.12);\n    color: #cbd5e1;\n}\n\n.venue-tooltip {\n    position: absolute;\n    z-index: 4300;\n    right: 0;\n    bottom: calc(100% + 0.5rem);\n    width: max-content;\n    max-width: min(250px, 76vw);\n    padding: 0.55rem 0.7rem;\n    border: 1px solid #475569;\n    border-radius: 0.5rem;\n    background: #020617;\n    color: #e2e8f0;\n    box-shadow: var(--shadow-light);\n    font-size: 0.8rem;\n    font-weight: 400;\n    line-height: 1.35;\n    text-align: left;\n    white-space: normal;\n    opacity: 0;\n    visibility: hidden;\n    pointer-events: none;\n    transform: translateY(0.25rem);\n    transition:\n        opacity 0.16s ease,\n        transform 0.16s ease,\n        visibility 0.16s ease;\n}\n\n.venue-compact:hover .venue-tooltip,\n.venue-compact:focus-within .venue-tooltip,\n.venue-compact.is-open .venue-tooltip {\n    opacity: 1;\n    visibility: visible;\n    transform: translateY(0);\n}\n\n/* =========================================\n   ===== EWIGE RANGLISTE ====================\n   ========================================= */\n\n.table-ewigeRangliste {\n    width: 100%;\n    max-width: 680px;\n    margin: 2rem auto;\n    border: 1px solid #334155;\n    border-collapse: separate;\n    border-spacing: 0;\n    border-radius: var(--space-m);\n    overflow: hidden;\n    background: rgba(15, 23, 42, 0.52);\n    box-shadow: var(--shadow-light);\n    font-family: Arial, sans-serif;\n    font-size: 0.95rem;\n}\n\n.table-ewigeRangliste thead {\n    background: rgba(56, 189, 248, 0.12);\n}\n\n.table-ewigeRangliste thead th {\n    padding: 0.7rem 0.75rem;\n    border-bottom: 1px solid #475569;\n    color: var(--accent);\n    font-weight: 700;\n    letter-spacing: 0.01em;\n    text-align: left;\n}\n\n.table-ewigeRangliste tbody tr {\n    background: rgba(15, 23, 42, 0.36);\n    opacity: 1;\n    transform: none;\n}\n\n.table-ewigeRangliste tbody th[scope="row"],\n.table-ewigeRangliste tbody td {\n    padding: 0.62rem 0.75rem;\n    border-bottom: 1px solid rgba(71, 85, 105, 0.72);\n    background: transparent;\n    color: var(--text-main);\n    line-height: 1.3;\n}\n\n.table-ewigeRangliste tbody th[scope="row"] {\n    width: 16%;\n    text-align: left;\n    font-weight: 700;\n}\n\n/* Fallback für ältere Ranglisten-Zeilen ohne semantisches Zeilen-TH. */\n.table-ewigeRangliste tbody td:first-child {\n    width: 70px;\n    text-align: center;\n    font-weight: 700;\n}\n\n.table-ewigeRangliste tbody td:nth-child(2) {\n    width: 64%;\n    text-align: left;\n}\n\n.table-ewigeRangliste tbody td:last-child {\n    width: 20%;\n    text-align: right;\n    font-weight: 600;\n}\n\n.table-ewigeRangliste tbody tr:last-child > * {\n    border-bottom: 0;\n}\n\n.table-ewigeRangliste tbody tr:hover {\n    background: rgba(56, 189, 248, 0.09);\n    transition: background-color 0.2s ease;\n}\n\n.table-search {\n    display: block;\n    width: 100%;\n    max-width: 680px;\n    margin: 1rem auto;\n    padding: 0.5rem;\n    border: 1px solid #475569;\n    border-radius: var(--space-s);\n    background: #f8fafc;\n    color: #0f172a;\n    font-size: 1rem;\n}\n\n.table-ewigeRangliste tbody tr.ranking-fade-ready {\n    animation: rankingReverseFade 0.16s ease-out both;\n    animation-delay: var(--ranking-fade-delay, 0ms);\n}\n\n@keyframes rankingReverseFade {\n    from {\n        opacity: 0.72;\n        transform: translateY(2px);\n    }\n    to {\n        opacity: 1;\n        transform: translateY(0);\n    }\n}\n\n/* =========================================\n   ===== KOMPAKTE TABELLEN BIS 768 PX =======\n   ========================================= */\n\n@media (max-width: 768px) {\n    .table-scroll--compact {\n        width: 100%;\n        max-width: 100%;\n        overflow: visible;\n        overscroll-behavior: auto;\n    }\n\n    .table-scroll--compact > table.table-compact-mobile {\n        width: 100%;\n        max-width: 100%;\n        min-width: 0;\n    }\n\n    table.table-compact-mobile {\n        display: table;\n        width: 100%;\n        min-width: 0;\n        table-layout: fixed;\n        font-size: clamp(0.68rem, 2.25vw, 0.82rem);\n    }\n\n    table.table-compact-mobile > thead {\n        display: table-header-group;\n        position: static;\n        width: auto;\n        height: auto;\n        margin: 0;\n        overflow: visible;\n        clip: auto;\n        white-space: normal;\n    }\n\n    table.table-compact-mobile > thead > tr {\n        display: table-row;\n        width: auto;\n    }\n\n    table.table-compact-mobile > tbody {\n        display: table-row-group;\n        width: auto;\n    }\n\n    table.table-compact-mobile > tbody > tr {\n        display: table-row;\n        width: auto;\n        padding: 0;\n        border: 0;\n        border-radius: 0;\n        background: transparent;\n        box-shadow: none;\n    }\n\n    table.table-compact-mobile > thead th,\n    table.table-compact-mobile > tbody td {\n        display: table-cell;\n        min-width: 0;\n        box-sizing: border-box;\n        padding: 0.55rem 0.25rem;\n        overflow-wrap: anywhere;\n        hyphens: auto;\n        vertical-align: middle;\n    }\n\n    table.table-compact-mobile > thead th {\n        overflow-wrap: normal;\n        word-break: normal;\n        hyphens: none;\n        white-space: nowrap;\n        line-height: 1.2;\n    }\n\n    table.table-compact-mobile > tbody td::before {\n        content: none;\n    }\n\n    table.table-compact-mobile .responsive-label--desktop,\n    table.table-compact-mobile .responsive-value--desktop,\n    table.table-compact-mobile .venue-full {\n        display: none;\n    }\n\n    table.table-compact-mobile .responsive-label--mobile,\n    table.table-compact-mobile .responsive-value--mobile {\n        display: inline;\n    }\n\n    table.table-compact-mobile .venue-compact {\n        display: inline-flex;\n    }\n\n    /* Ligatabelle: Rang | Team | S-U-N | Spiele | +/- | Punkte */\n    table.table-compact-mobile--league .table-mobile-only {\n        display: table-cell;\n    }\n\n    table.table-compact-mobile--league .table-col--matches,\n    table.table-compact-mobile--league .table-col--wins,\n    table.table-compact-mobile--league .table-col--draws,\n    table.table-compact-mobile--league .table-col--losses {\n        display: none;\n    }\n\n    table.table-compact-mobile--league .table-col--rank {\n        width: 8%;\n        text-align: left;\n    }\n\n    table.table-compact-mobile--league .table-col--team {\n        width: 35%;\n        text-align: left;\n    }\n\n    table.table-compact-mobile--league .table-col--record {\n        width: 14%;\n        text-align: center;\n        white-space: nowrap;\n    }\n\n    table.table-compact-mobile--league .table-col--games {\n        width: 16%;\n        text-align: center;\n        white-space: nowrap;\n    }\n\n    table.table-compact-mobile--league .table-col--difference {\n        width: 11%;\n        text-align: center;\n        white-space: nowrap;\n    }\n\n    table.table-compact-mobile--league .table-col--points {\n        width: 16%;\n        text-align: right;\n        white-space: nowrap;\n    }\n\n    /* Startseite: Dat. | Zeit | Team | Geg. | H/A | Erg. */\n    table.table-compact-mobile--next-games .table-col--date {\n        width: 18%;\n        text-align: left;\n    }\n\n    table.table-compact-mobile--next-games .table-col--time {\n        width: 14%;\n        text-align: center;\n        white-space: nowrap;\n    }\n\n    table.table-compact-mobile--next-games .table-col--team {\n        width: 13%;\n        text-align: left;\n        white-space: nowrap;\n    }\n\n    table.table-compact-mobile--next-games .table-col--opponent {\n        width: 31%;\n        text-align: left;\n    }\n\n    table.table-compact-mobile--next-games .table-col--venue {\n        width: 10%;\n        overflow: visible;\n        text-align: center;\n    }\n\n    table.table-compact-mobile--next-games .table-col--result {\n        width: 14%;\n        text-align: right;\n        white-space: nowrap;\n    }\n\n    /* Mannschaftsspielplan: Dat. | Zeit | Geg. | H/A | Erg. */\n    table.table-compact-mobile--schedule .table-mobile-only {\n        display: table-cell;\n    }\n\n    table.table-compact-mobile--schedule .table-col--venue:not(.table-mobile-only),\n    table.table-compact-mobile--schedule .table-col--opponent:not(.table-mobile-only) {\n        display: none;\n    }\n\n    table.table-compact-mobile--schedule .table-col--date {\n        width: 19%;\n        text-align: left;\n    }\n\n    table.table-compact-mobile--schedule .table-col--time {\n        width: 15%;\n        text-align: center;\n        white-space: nowrap;\n    }\n\n    table.table-compact-mobile--schedule .table-mobile-only.table-col--opponent {\n        width: 38%;\n        text-align: left;\n    }\n\n    table.table-compact-mobile--schedule .table-mobile-only.table-col--venue {\n        width: 11%;\n        overflow: visible;\n        text-align: center;\n    }\n\n    table.table-compact-mobile--schedule .table-col--result {\n        width: 17%;\n        text-align: right;\n        white-space: nowrap;\n    }\n\n    table.table-compact-mobile .table-status-row {\n        display: table-row;\n    }\n\n    table.table-compact-mobile .table-status-row td {\n        display: table-cell;\n        text-align: center;\n    }\n}\n\n/* =========================================\n   ===== WEITERE MOBILE ANPASSUNGEN =========\n   ========================================= */\n\n@media (max-width: 600px) {\n    .table-search {\n        max-width: 100%;\n    }\n}\n\n@media (max-width: 480px) {\n    table {\n        font-size: 0.85rem;\n    }\n\n    td,\n    th {\n        padding: var(--space-s);\n    }\n\n    table.table-compact-mobile {\n        font-size: clamp(0.63rem, 2.6vw, 0.76rem);\n    }\n\n    table.table-compact-mobile > thead th {\n        font-size: clamp(0.64rem, 2.65vw, 0.74rem);\n        letter-spacing: 0;\n    }\n\n    table.table-compact-mobile > tbody td,\n    table.table-compact-mobile > thead th {\n        padding: 0.5rem 0.16rem;\n    }\n\n    table.table-compact-mobile--next-games :is(th, td),\n    table.table-compact-mobile--schedule :is(th, td) {\n        padding-inline: 0.12rem;\n    }\n\n    .venue-badge {\n        width: 1.55rem;\n        height: 1.55rem;\n        font-size: 0.7rem;\n    }\n\n    .venue-tooltip {\n        right: -1rem;\n        max-width: min(220px, 82vw);\n    }\n}\n\n@media (prefers-reduced-motion: reduce) {\n    .venue-tooltip {\n        transition: none;\n    }\n\n    .table-ewigeRangliste tbody tr,\n    .table-ewigeRangliste tbody tr.animate,\n    .table-ewigeRangliste tbody tr.ranking-fade-ready {\n        opacity: 1 !important;\n        transform: none !important;\n        animation: none !important;\n    }\n}\n'}, 'assets/css/components/teams.css': {'before_sha256': '484f24f464f23e010bc87970e8d7e00324de0c47e1e0726637ed6af8c54eef73', 'after_sha256': '188d03736034d3f7895506781ed3c13329b6df2956228e52c13b7760dc5044c9', 'content': '/* Mannschaftsübersicht. Aus style.css unverändert ausgelagert. */\n\n/* =========================================\n   ===== 9. TEAMS GRID =====================\n   ========================================= */\n\n.teams-grid {\n    display: grid;\n    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));\n    gap: var(--space-xl);\n    padding: var(--space-m) var(--space-xl);\n}\n\n@media (max-width: 768px) {\n    .teams-grid {\n        grid-template-columns: 1fr;\n        padding-left: var(--space-m);\n        padding-right: var(--space-m);\n    }\n}\n'}, 'assets/css/components/ui-buttons.css': {'before_sha256': 'a306bcae69acc0221305693c9105e5cb6af5dfab7c08a1deb61e44e4946a8707', 'after_sha256': '7d3404d9079efb2e77a802b43d6b7b21afbcdaa2058783cb20406c4666235bdc', 'content': '/* UI-Hilfsklassen und Buttons. */\n\n/* =========================================\n   ===== UI ELEMENTE =======================\n   ========================================= */\n\nhr {\n    border: 0;\n    height: 2px;\n    background: var(--accent);\n    margin: var(--space-xl) 0;\n}\n\n.underline {\n    display: inline-block;\n    border-bottom: 2px solid currentColor;\n}\n\n.u-text-center {\n    text-align: center;\n}\n\n/* =========================================\n   ===== BUTTONS ===========================\n   ========================================= */\n\n.button {\n    display: inline-block;\n    padding: var(--space-m) var(--space-l);\n    border-radius: var(--space-m);\n    background: var(--bg-secondary);\n    color: var(--text-main);\n    box-shadow: var(--shadow-light);\n    text-decoration: none;\n    cursor: pointer;\n    transition: transform 0.2s ease, box-shadow 0.2s ease, background 0.2s ease;\n}\n\n.button:hover {\n    transform: translateY(-3px);\n    background: var(--bg-main);\n    box-shadow: var(--shadow-heavy);\n}\n\n.button--card {\n    display: block;\n    padding: var(--space-xl);\n    text-align: center;\n}\n\n.button img {\n    display: block;\n    max-width: 100%;\n    height: auto;\n    margin: 0 auto;\n}\n\n.button:focus {\n    outline: 2px solid var(--accent);\n    outline-offset: 2px;\n}\n\n.button:active {\n    transform: translateY(0);\n    box-shadow: var(--shadow-light);\n}\n\n@media (max-width: 480px) {\n    .button--card {\n        padding: var(--space-l);\n    }\n}\n\n@media (prefers-reduced-motion: reduce) {\n    .button {\n        transition: none !important;\n    }\n}\n'}, 'assets/css/layout/footer.css': {'before_sha256': '3652ceb1aa91c35f80ebb9c38dd416879e6ee749b22588f3dc0ff48f3618ed05', 'after_sha256': '44e72f9337e37dd193f97dc5bf216bbecfe40e785a18416528bf32ab4f595f56', 'content': '/* Footer. Aus style.css unverändert ausgelagert. */\n\n/* =========================================\n   ===== 15. FOOTER ========================\n   ========================================= */\n\n.footer {\n    display: grid;\n    text-align: center;\n    grid-template-columns: repeat(5, 1fr);\n    padding: var(--space-xl);\n    color: var(--text-muted);\n}\n\n.footer-links {\n    margin-top: var(--space-m);\n    display: flex;\n    justify-content: center;\n    gap: var(--space-l);\n}\n\n.footer a {\n    color: var(--text-muted);\n    text-decoration: none;\n}\n\n.footer a:hover {\n    color: var(--accent);\n}\n\n.footer a:focus-visible {\n    outline: 2px solid var(--accent);\n    outline-offset: 3px;\n    border-radius: 2px;\n}\n\n@media (max-width: 768px) {\n    .footer {\n        grid-template-columns: 1fr;\n        gap: var(--space-m);\n    }\n\n    .footer-links {\n        flex-wrap: wrap;\n    }\n}\n'}, 'assets/css/layout/grid-boxes.css': {'before_sha256': '75c964527cb6a8d9579edf95a5e207ef51448d926a707521783b7cc1ab633416', 'after_sha256': 'a87f693349e755073fa9b5f9dae638b73080d77dd29749f719e362c183d4f1fa', 'content': '/* Grid-Layouts und Box-Komponenten. */\n\n/* =========================================\n   ===== GRID LAYOUT =======================\n   ========================================= */\n\n.grid {\n    display: grid;\n    grid-template-columns: 1fr 1fr;\n    gap: var(--space-m);\n    padding: var(--space-m) var(--space-xl);\n    align-items: stretch;\n}\n\n.grid-home-wrapper {\n    display: flex;\n    flex-direction: column;\n    gap: var(--space-m);\n}\n\n.grid-home-firstLine {\n    display: grid;\n    grid-template-columns: minmax(18rem, 0.9fr) minmax(34rem, 1.35fr);\n    gap: var(--space-m);\n    padding: 0 var(--space-xl);\n    align-items: stretch;\n}\n\n.grid-home-secondLine {\n    display: grid;\n    grid-template-columns: minmax(28rem, 1.35fr) minmax(20rem, 0.85fr);\n    gap: var(--space-m);\n    padding: 0 var(--space-xl);\n    align-items: stretch;\n}\n\n.grid > *,\n.grid-home-firstLine > *,\n.grid-home-secondLine > * {\n    min-width: 0;\n}\n\n.full-width {\n    grid-column: 1 / -1;\n    padding: var(--space-m) var(--space-xl);\n}\n\n.grid-button {\n    display: grid;\n    grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));\n    gap: var(--space-l);\n    padding: var(--space-m) var(--space-xl);\n    margin-top: auto;\n}\n\n/* =========================================\n   ===== BOXEN =============================\n   ========================================= */\n\n.box,\n.team-box {\n    padding: var(--space-xl);\n    border-radius: var(--space-m);\n    background: var(--bg-secondary);\n    box-shadow: var(--shadow-light);\n    transition: transform 0.2s ease, box-shadow 0.2s ease;\n}\n\n/* Reine Inhaltsboxen bleiben ruhig; Interaktion wird nur an Links und Buttons signalisiert. */\n.box:hover,\n.team-box:hover {\n    transform: none;\n    box-shadow: var(--shadow-light);\n}\n\n.team-box ul,\n.team-box ol {\n    padding-left: 1.2em;\n    margin: 0 0 var(--space-m) 0;\n}\n\n.team-box li {\n    margin-bottom: 0;\n}\n\n.column {\n    display: grid;\n    gap: var(--space-m);\n}\n\n@media (max-width: 1180px) {\n    .grid-home-firstLine,\n    .grid-home-secondLine {\n        grid-template-columns: minmax(0, 1fr);\n    }\n}\n\n@media (max-width: 768px) {\n    .grid,\n    .grid-home-firstLine,\n    .grid-home-secondLine,\n    .full-width,\n    .grid-button {\n        grid-template-columns: 1fr;\n        padding-left: var(--space-m);\n        padding-right: var(--space-m);\n    }\n}\n\n@media (max-width: 480px) {\n    .box,\n    .team-box {\n        padding: var(--space-l);\n    }\n\n    .grid-button {\n        grid-template-columns: 1fr;\n    }\n}\n\n@media (prefers-reduced-motion: reduce) {\n    .box,\n    .team-box {\n        transition: none !important;\n    }\n}\n'}, 'assets/css/layout/header-navigation.css': {'before_sha256': '6ca86b8955e1c7172a8b7277ede4890d8c282c350e5eb9e8390c0b9ffad4abb0', 'after_sha256': 'a4d3d5d079886d7c15186327a3d5aa10c05c07f4cc40891d5fd001452045e42f', 'content': '/* Header und Hauptnavigation. */\n\n/* =========================================\n   ===== HEADER ============================\n   ========================================= */\n\n.top-bar {\n    position: sticky;\n    top: 0;\n    z-index: 1000;\n}\n\n#header-container,\n.site-header {\n    position: relative;\n    background: var(--bg-main);\n    text-align: center;\n    padding: var(--space-m);\n}\n\n.logo {\n    position: absolute;\n    left: var(--space-l);\n    top: 50%;\n    transform: translateY(-50%);\n    height: 75px;\n}\n\n.header-text {\n    text-align: center;\n}\n\n.site-title {\n    display: inline-block;\n    color: var(--text-main);\n    font-size: 2em;\n    font-weight: 700;\n    line-height: 1.2;\n    text-decoration: none;\n}\n\n.site-title:hover {\n    color: var(--accent);\n}\n\n.site-title:focus-visible,\n.menu a:focus-visible {\n    outline: 2px solid var(--accent);\n    outline-offset: 3px;\n    border-radius: 2px;\n}\n\n.menu a[aria-current="page"] {\n    color: var(--accent);\n    text-decoration: underline;\n    text-underline-offset: 0.3em;\n}\n\n/* =========================================\n   ===== NAVIGATION ========================\n   ========================================= */\n\nnav {\n    background: var(--bg-navigation);\n    text-align: center;\n}\n\n.menu {\n    list-style: none;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    flex-wrap: wrap;\n    gap: var(--space-xl);\n    padding: var(--space-m);\n}\n\n.menu li {\n    position: relative;\n}\n\n.menu > li {\n    display: flex;\n    align-items: center;\n    min-height: 36px;\n}\n\n.menu a {\n    text-decoration: none;\n    color: var(--text-main);\n    transition: color 0.2s ease;\n}\n\n.menu a:hover {\n    color: var(--accent);\n}\n\n/* Dropdown-Menü */\n.submenu {\n    position: absolute;\n    top: 100%;\n    left: 50%;\n    z-index: 1001;\n    background: var(--bg-secondary);\n    box-shadow: var(--shadow-heavy);\n    border-radius: var(--space-m);\n    list-style: none;\n    padding: var(--space-s);\n    white-space: nowrap;\n    opacity: 0;\n    visibility: hidden;\n    transform: translateX(-50%) translateY(-10px);\n    transition: opacity 0.3s ease, transform 0.3s ease;\n}\n\n.submenu li {\n    margin: 0;\n}\n\n.submenu li + li {\n    margin-top: 4px;\n}\n\n.submenu a {\n    display: block;\n    padding: var(--space-s) var(--space-l);\n    border-radius: var(--space-s);\n    color: var(--text-main);\n    text-decoration: none;\n    transition: background 0.2s ease, transform 0.15s ease;\n}\n\n.submenu a:hover {\n    background: var(--bg-main);\n    transform: translateX(3px);\n}\n\n.dropdown:hover .submenu,\n.dropdown:focus-within .submenu,\n.dropdown.is-open .submenu {\n    opacity: 1;\n    visibility: visible;\n    transform: translateX(-50%) translateY(0);\n}\n\n.dropdown > .dropdown-link {\n    display: inline-flex;\n    align-items: center;\n    gap: 0.45rem;\n    min-height: 36px;\n    padding: 0.25rem 0;\n    line-height: 1.25;\n}\n\n.dropdown-link__indicator {\n    display: inline-grid;\n    place-items: center;\n    width: 1rem;\n    height: 1rem;\n    color: var(--accent);\n    font-size: 0.78em;\n    transition: transform 0.2s ease;\n}\n\n.dropdown.is-open > .dropdown-link .dropdown-link__indicator {\n    transform: rotate(180deg);\n}\n\n@media (hover: none), (max-width: 768px) {\n    .dropdown:hover .submenu {\n        opacity: 0;\n        visibility: hidden;\n        transform: translateX(-50%) translateY(-10px);\n    }\n\n    .dropdown.is-open .submenu,\n    .dropdown:focus-within .submenu {\n        opacity: 1;\n        visibility: visible;\n        transform: translateX(-50%) translateY(0);\n    }\n}\n\n@media (max-width: 1024px) {\n    .menu {\n        gap: var(--space-m);\n    }\n\n    .menu a {\n        font-size: 0.95rem;\n    }\n}\n\n@media (max-width: 768px) {\n    #header-container,\n    .site-header {\n        padding: var(--space-l) var(--space-m);\n    }\n\n    .logo {\n        position: static;\n        height: 60px;\n        margin-bottom: var(--space-s);\n        transform: none;\n    }\n\n    .menu {\n        flex-direction: row;\n        flex-wrap: wrap;\n        align-items: center;\n        justify-content: center;\n        gap: var(--space-s) var(--space-m);\n    }\n\n    .submenu {\n        position: absolute;\n        top: 100%;\n        left: 50%;\n        z-index: 2000;\n        white-space: nowrap;\n        box-shadow: var(--shadow-heavy);\n        transform: translateX(-50%) translateY(-10px);\n    }\n\n    .dropdown:hover .submenu,\n    .dropdown:focus-within .submenu {\n        transform: translateX(-50%) translateY(0);\n    }\n}\n\n@media (max-width: 480px) {\n    .site-title {\n        font-size: 1.65em;\n    }\n}\n\n@media (prefers-reduced-motion: reduce) {\n    .dropdown-link__indicator,\n    .submenu {\n        transition: none !important;\n    }\n}\n'}, 'assets/css/main.css': {'before_sha256': '7b66676e76c9443a1c018981bf5fd5bd20f36e856c43131234263f5dffb93eea', 'after_sha256': 'bb9ea51da3ae9fb083a7590f6eba537af0fb5c89d903f6323f2f2260461acb56', 'content': '/*\n * Zentraler Einstiegspunkt für die Website-Gestaltung.\n * Die Website lädt diese Datei direkt; die Imports bilden die CSS-Module ab.\n */\n@import url("./base/reset.css");\n@import url("./base/theme.css");\n@import url("./layout/header-navigation.css");\n@import url("./layout/grid-boxes.css");\n@import url("./components/page-content.css");\n@import url("./components/animations.css");\n@import url("./components/news-slider.css");\n@import url("./components/teams.css");\n@import url("./components/tables.css");\n@import url("./components/ui-buttons.css");\n@import url("./components/maps-consent.css");\n@import url("./layout/footer.css");\n@import url("./components/contact-form.css");\n@import url("./components/gallery.css");\n@import url("./components/robustness.css");\n@import url("./components/accessibility.css");\n'}}
RESPONSIVE_CSS = 'assets/css/responsive.css'
RESPONSIVE_BEFORE_SHA256 = 'd2f74fb299df5ef3b42bfbe676c75d50f026beb344cde8501a8bdbb9d1dbdd38'


def sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()

def read(path: str) -> str:
    return (ROOT / path).read_text(encoding="utf-8")

def write(path: str, content: str) -> None:
    (ROOT / path).write_text(content, encoding="utf-8")

def replace_exact(path: str, old: str, new: str, label: str) -> bool:
    text = read(path)
    if new in text and old not in text:
        return False
    if old not in text:
        raise RuntimeError(f"{label}: erwarteter Ausgangstext fehlt in {path}.")
    write(path, text.replace(old, new, 1))
    return True

def apply_css_targets() -> list[str]:
    changed = []
    for rel, spec in CSS_TARGETS.items():
        path = ROOT / rel
        if not path.exists():
            raise RuntimeError(f"CSS-Datei fehlt: {rel}")
        current_hash = sha256(path)
        if current_hash == spec["after_sha256"]:
            continue
        if current_hash != spec["before_sha256"]:
            raise RuntimeError(
                f"{rel} entspricht weder dem geprüften Ausgangs- noch dem Zielstand. "
                "Cleanup wird zur Sicherheit abgebrochen."
            )
        path.write_text(spec["content"], encoding="utf-8")
        if sha256(path) != spec["after_sha256"]:
            raise RuntimeError(f"Hash-Prüfung nach Schreiben fehlgeschlagen: {rel}")
        changed.append(rel)

    responsive = ROOT / RESPONSIVE_CSS
    if responsive.exists():
        if sha256(responsive) != RESPONSIVE_BEFORE_SHA256:
            raise RuntimeError(f"{RESPONSIVE_CSS} hat einen unbekannten Stand und wird nicht gelöscht.")
        responsive.unlink()
        changed.append(RESPONSIVE_CSS)
    return changed

def ensure_no_startpage_link_target() -> None:
    hits = []
    for suffix in ("*.html", "*.js"):
        for path in ROOT.rglob(suffix):
            rel = path.relative_to(ROOT)
            if rel.parts and rel.parts[0] == "tools":
                continue
            try:
                text = path.read_text(encoding="utf-8")
            except UnicodeDecodeError:
                continue
            if "link-spieleStartseite" in text:
                hits.append(str(rel))
    if hits:
        raise RuntimeError(
            "spieleStartseite kann nicht aus links.json entfernt werden; Referenzen: "
            + ", ".join(sorted(hits))
        )

def patch_config() -> bool:
    path = "assets/python/config.py"
    text = read(path)
    original = text
    season_decl = 'SAISON = "26--27"'
    if "SAISON =" not in text:
        anchor = "from datetime import datetime, timedelta\n\n"
        if anchor not in text:
            raise RuntimeError("config.py: Import-Anker für SAISON fehlt.")
        text = text.replace(anchor, anchor + season_decl + "\n\n", 1)
    elif season_decl not in text:
        raise RuntimeError("config.py enthält bereits eine unerwartete SAISON-Konfiguration.")

    text = text.replace("TTBW/26--27/", "TTBW/{SAISON}/")
    lines = []
    for line in text.splitlines(keepends=True):
        if "https://www.mytischtennis.de/click-tt/TTBW/{SAISON}/" in line:
            line = re.sub(
                r'(?<!f)"https://www\.mytischtennis\.de/click-tt/TTBW/\{SAISON\}/',
                'f"https://www.mytischtennis.de/click-tt/TTBW/{SAISON}/',
                line,
                count=1,
            )
        lines.append(line)
    text = "".join(lines)

    start_old = '        "type": "startseite"\n'
    start_new = '        "type": "startseite",\n        "export_link": False\n'
    if start_new not in text:
        if start_old not in text:
            raise RuntimeError("config.py: Startseiten-Konfiguration konnte nicht erweitert werden.")
        text = text.replace(start_old, start_new, 1)

    text = text.replace('"url": "http://www.jako.com/"', '"url": "https://www.jako.com/"')
    if text.count('26--27') != 1 or season_decl not in text or 'TTBW/26--27/' in text:
        raise RuntimeError("config.py: Saison wurde nicht eindeutig zentralisiert.")
    if text != original:
        write(path, text)
        return True
    return False

def patch_scraper_links_export() -> bool:
    return replace_exact(
        "assets/python/scraper.py",
        '        "spielplaene": SPIELPLAENE,\n',
        '        "spielplaene": [plan for plan in SPIELPLAENE if plan.get("export_link", True)],\n',
        "links.json-Export",
    )

def patch_links_json() -> bool:
    ensure_no_startpage_link_target()
    path = ROOT / "assets/data/links.json"
    data = json.loads(path.read_text(encoding="utf-8"))
    changed = False
    plans = data.get("spielplaene", [])
    filtered = [plan for plan in plans if plan.get("id") != "spieleStartseite"]
    if filtered != plans:
        data["spielplaene"] = filtered
        changed = True
    for group in data.get("links", []):
        for link in group.get("links", []):
            if link.get("id") == "sponsor1" and link.get("name") == "JAKO" and link.get("url") == "http://www.jako.com/":
                link["url"] = "https://www.jako.com/"
                changed = True
    if changed:
        path.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")
    return changed

def patch_header() -> bool:
    return replace_exact(
        "components/header.html",
        '<header class="top-bar">',
        '<header class="site-header">',
        "Header-Struktur",
    )

def patch_footer_year() -> bool:
    return replace_exact(
        "components/footer.html",
        '<p>© 2026 TTF Laudenbach</p>',
        '<p>© <span data-current-year>2026</span> TTF Laudenbach</p>',
        "Footer-Jahr",
    )

def patch_site_components_year() -> bool:
    path = "assets/js/core/site-components.js"
    text = read(path)
    original = text
    fn = (
        'function updateCurrentYear(root = document) {\n'
        '    root.querySelectorAll("[data-current-year]").forEach(element => {\n'
        '        element.textContent = String(new Date().getFullYear());\n'
        '    });\n'
        '}\n\n'
    )
    if "function updateCurrentYear(" not in text:
        anchor = "export async function initSiteComponents() {"
        if anchor not in text:
            raise RuntimeError("site-components.js: Export-Anker fehlt.")
        text = text.replace(anchor, fn + anchor, 1)
    call = "    updateCurrentYear();\n\n"
    if call not in text:
        anchor = "    return results;\n}"
        if anchor not in text:
            raise RuntimeError("site-components.js: Return-Anker fehlt.")
        text = text.replace(anchor, call + anchor, 1)
    if text != original:
        write(path, text)
        return True
    return False

def remove_feature_animation_calls() -> list[str]:
    specs = {
        "assets/js/features/links.js": "        initAnimations();\n",
        "assets/js/features/news-slider.js": "        initAnimations(newsContainer);\n",
        "assets/js/features/gallery.js": "            initAnimations(section);\n",
    }
    changed = []
    import_line = 'import { initAnimations } from "./animations.js";\n'
    for rel, call in specs.items():
        text = read(rel)
        original = text
        text = text.replace(import_line, "", 1)
        text = text.replace(call, "", 1)
        if "initAnimations(" in text or 'from "./animations.js"' in text:
            raise RuntimeError(f"{rel} enthält nach dem Cleanup noch eine Feature-eigene Animationsinitialisierung.")
        if text != original:
            write(rel, text)
            changed.append(rel)
    return changed

def patch_todo() -> bool:
    path = "ToDoList.txt"
    text = read(path)
    old = '- In der Galerie, der "Galerien"-Block schwebt wenn man nach unten scrollt. Sollte dann nach oben rutschen.\n'
    if old not in text:
        return False
    write(path, text.replace(old, "", 1))
    return True

def verify_target_state() -> None:
    if (ROOT / "assets/css/responsive.css").exists():
        raise RuntimeError("responsive.css existiert nach dem Cleanup noch.")
    if "responsive.css" in read("assets/css/main.css"):
        raise RuntimeError("main.css importiert responsive.css noch.")
    a11y = read("assets/css/components/accessibility.css")
    forbidden = [".news-", ".iframe-", ".images-", ".site-title", ".menu ", ".footer ", ".table-ewige", ".box", ".team-box", ".button"]
    leftovers = [token for token in forbidden if token in a11y]
    if leftovers:
        raise RuntimeError("accessibility.css enthält noch Komponentenregeln: " + ", ".join(leftovers))
    config = read("assets/python/config.py")
    if config.count('SAISON = "26--27"') != 1 or "TTBW/26--27/" in config:
        raise RuntimeError("Saison-Konfiguration ist nicht zentralisiert.")
    if '"url": "http://www.jako.com/"' in config:
        raise RuntimeError("JAKO verwendet in config.py noch HTTP.")
    links = json.loads(read("assets/data/links.json"))
    if any(plan.get("id") == "spieleStartseite" for plan in links.get("spielplaene", [])):
        raise RuntimeError("links.json enthält spieleStartseite weiterhin.")
    for group in links.get("links", []):
        for link in group.get("links", []):
            if link.get("id") == "sponsor1" and link.get("url") != "https://www.jako.com/":
                raise RuntimeError("JAKO-URL ist in links.json nicht HTTPS.")
    if '<header class="top-bar">' in read("components/header.html"):
        raise RuntimeError("Header besitzt noch die doppelte top-bar-Klasse.")
    if "data-current-year" not in read("components/footer.html"):
        raise RuntimeError("Footer besitzt keinen Jahres-Platzhalter.")
    if "updateCurrentYear();" not in read("assets/js/core/site-components.js"):
        raise RuntimeError("Footer-Jahr wird nicht initialisiert.")
    for rel in ("assets/js/features/links.js", "assets/js/features/news-slider.js", "assets/js/features/gallery.js"):
        text = read(rel)
        if "initAnimations(" in text or 'from "./animations.js"' in text:
            raise RuntimeError(f"{rel} enthält noch redundante Animationsinitialisierung.")

def main() -> None:
    # B3 zuerst validieren, bevor irgendeine Datei verändert wird.
    ensure_no_startpage_link_target()

    changed = []
    changed.extend(apply_css_targets())
    if patch_config(): changed.append("assets/python/config.py")
    if patch_scraper_links_export(): changed.append("assets/python/scraper.py")
    if patch_links_json(): changed.append("assets/data/links.json")
    if patch_header(): changed.append("components/header.html")
    if patch_footer_year(): changed.append("components/footer.html")
    if patch_site_components_year(): changed.append("assets/js/core/site-components.js")
    changed.extend(remove_feature_animation_calls())
    if patch_todo(): changed.append("ToDoList.txt")
    verify_target_state()
    unique = list(dict.fromkeys(changed))
    if unique:
        print("Repo-Cleanup B/C/D angewendet:")
        for rel in unique: print(f"- {rel}")
    else:
        print("Repo-Cleanup B/C/D: Zielzustand bereits vollständig vorhanden.")

if __name__ == "__main__":
    main()
